Mesh<Point, double> mesh;
for (auto eit = rt.finite_edges_begin(); eit != rt.finite_edges_end(); ++eit) {
    RT::Edge e = *eit;
    if (!is_small_edge(rt, e, threshold)) continue;

    std::vector<RT::Cell_handle> incident;
    rt.incident_cells(e, std::back_inserter(incident));
    if (incident.empty()) continue;

    std::vector<unsigned> face_vertices;
    face_vertices.reserve(incident.size());

    for (auto const& cell : incident) {
        Point p = rt.dual(cell);
        unsigned idx = static_cast<unsigned>(mesh.vertices.size());
        mesh.vertices.push_back(p);
        face_vertices.push_back(idx);
    }

    double edge_len = std::sqrt(rt.segment(e).squared_length());
    mesh.push_back(face_vertices, edge_len);
}
return mesh;

